	/**
	 * Default Constructor
	 */
    public CustomerAddressService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CustomerAddressEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CustomerAddressRepository.class) );
		this.validator		= applicationContext.getBean(CustomerAddressValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CustomerAddress
	 */
		public CustomerAddress createCustomerAddress( CreateCustomerAddressCommand command ) {

		CustomerAddress entity = new CustomerAddress();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCustomerAddressId( command.getCustomerAddressId() );
            entity.setLabel( command.getLabel() );
            entity.setAddress( command.getAddress() );
            entity.setAsDefaultShipping( command.getAsDefaultShipping() );
            entity.setAsDefaultBilling( command.getAsDefaultBilling() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CustomerAddress {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCustomerAddressCommand
	 * @return		CustomerAddress
	 */
	public CustomerAddress updateCustomerAddress( UpdateCustomerAddressCommand command ) {

		CustomerAddress entity = new CustomerAddress();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCustomerAddressId( command.getCustomerAddressId() );
            entity.setLabel( command.getLabel() );
            entity.setAddress( command.getAddress() );
            entity.setAsDefaultShipping( command.getAsDefaultShipping() );
            entity.setAsDefaultBilling( command.getAsDefaultBilling() );
            entity.setCustomer( command.getCustomer() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of CustomerAddress {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCustomerAddressCommand
	 */
	public void delete( DeleteCustomerAddressCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCustomerAddressId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of CustomerAddress {0} ", id );

	}

	/**
	 * Method to retrieve the CustomerAddress via CustomerAddressFetchOneSummary
	 * @param 	summary CustomerAddressFetchOneSummary
	 * @return 	CustomerAddressFetchOneResponse
	 */
	public CustomerAddress getCustomerAddress( CustomerAddressFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CustomerAddressFetchOneSummary arg cannot be null" );

		CustomerAddress entity = null;
		UUID id = summary.getCustomerAddressId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a CustomerAddress using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all CustomerAddresss
	 *
	 * @return 	List<CustomerAddress>
	 */
    public List<CustomerAddress> getAllCustomerAddress() {
		List<CustomerAddress> list = projector.findAll( new FindAllCustomerAddressQuery() );
		return list;
	}

	/**
	 * assign Customer on CustomerAddress
	 * @param		command AssignCustomerToCustomerAddressCommand
	 */
	public void assignCustomer( AssignCustomerToCustomerAddressCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getCustomerAddressId(), command.getAssignment());

	}

	/**
	 * unAssign Customer on CustomerAddress
	 * @param		command UnAssignCustomerFromCustomerAddressCommand
	 */
	public void unAssignCustomer( UnAssignCustomerFromCustomerAddressCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignCustomer(command.getCustomerAddressId());
	}
	




